INSERT INTO course_catalog
    (id, uuid, tenant_id, organization_id, course_code, category_id, primary_instructor_id, title, subtitle, summary, description, learning_objectives_json, target_audience_json, prerequisites_json, difficulty_level, language_code, cover_resource_snapshot, tags_json, estimated_duration_seconds, lesson_count_snapshot, student_count_snapshot, rating_score_snapshot, rating_count_snapshot, external_source_id, price_amount, original_price_amount, currency, is_free, is_collection, course_kind, author_user_id, author_display_name, review_round, visibility, publish_status, published_at, status, created_at, created_by, updated_at, updated_by, version)
VALUES
    ('course-bili-bv18v411d7m5', 'course-bili-bv18v411d7m5', '100001', '0', 'BILI-DATA-092', 'course-category-data', 'instructor-bili-578575099', 'SPSS统计分析教程：入门篇（2024版）', '42 讲完整课程 · 7 小时 41 分钟', '适合人群： 工作中有统计分析需求，希望能够快速掌握SPSS软件基本操作的朋友。你将会学到： 协助学员快速掌握SPSS在文件管理、数据录入、数据管理、图表绘制、统计描述等方面的基本操作。课程简介： SPSS是应用范围最', '课程简介：适合人群： 工作中有统计分析需求，希望能够快速掌握SPSS软件基本操作的朋友。你将会学到： 协助学员快速掌握SPSS在文件管理、数据录入、数据管理、图表绘制、统计描述等方面的基本操作。课程简介： SPSS是应用范围最广的统计软件，也是非统计专业人员青睐的统计软件，掌握其基本操作方法在各行业人员中都有强烈的需求。本课程为《SPSS统计分析视频教程》（2024版）的第一部分，内容与教材《SPSS统计分析基础教程》（第4版）相配套，主要目的是协助学员快速了解SPSS在文件管理、数据录入、数据管理、图表绘制、统计描述等各方面的基本操作。学员可在此基础上进一步学习后续的基础篇、高级篇，以全面掌握SPSS的各种统计分析和建模功能。本课程使用的数据均来自配套教材附带数据包，课程结构：共 6 章 42 讲，累计时长 7 小时 41 分钟，视频画面与课程封面同源。学习方式：按章节顺序观看即可，每讲均可在课程播放器中直接播放 B 站官方视频。', '["掌握 Excel、SQL 与 Python 三件套的数据处理能力","独立完成数据清洗、建模、可视化与结论输出","理解指标体系与业务分析方法，能撰写可落地的分析报告","具备数据分析师岗位求职所需的项目与作品"]', '["零基础转行数据分析的职场人","需要提升数据能力的运营、产品与市场人员","在校学生与应届生"]', '["熟悉电脑基本操作","无需编程基础，课程从零讲起"]', 'beginner', 'zh-CN', 'https://i0.hdslb.com/bfs/archive/6fce544be1307abdacc24603f7ddf832b31f449a.jpg', '["数据分析","Excel","SQL","SPSS统计分析教程","入门篇","2024版"]', 27718, 42, 26026, '4.5', 7108, 'BV18V411d7M5', '49.00', '78.40', 'CNY', 0, 0, 'standard', NULL, '张文彤', 0, 'tenant', 'published', '2020-05-08T07:26:25.000Z', 'active', CURRENT_TIMESTAMP::text, 'catalog-seed', CURRENT_TIMESTAMP::text, 'catalog-seed', 0)
